/* The room starts: the Cradle, the hostages tied or free, Preax.
 * [MSG_TICK 01 00 00] */
static void love5_StartRoom(void)
{
    uint16_t ax = 0;
    uint16_t s0;
    uint16_t s1;
    uint16_t s2;
    uint16_t s3;
    svc_Sfx(N_LOV5LOOP);
    svc_Anim0(8, N_s3r6c1, 0x27, 0xA9, 0);
    s0 = 0;
    s1 = 0xA6;
    s2 = 0x28;
    s3 = N_marcus2;
    if (rv_freed_hostages == 1) {
        s3 = N_marcusst;
    }
    svc_Anim0(0xA, s3, s2, s1, s0);
    s0 = 0;
    s1 = 0xAC;
    s2 = 0x49;
    s3 = N_s3gtup2;
    if (rv_freed_hostages == 1) {
        s3 = N_s3gtupst;
    }
    svc_Anim0(0xB, s3, s2, s1, s0);
    s0 = 0;
    s1 = 0xBA;
    s2 = 0x116;
    s3 = N_s3r6r2;
    if (rv_preax_cured == 1) {
        s3 = N_s3r6r3;
    }
    svc_Anim0(9, s3, s2, s1, s0);
    if (rv_n2o_released == 1) {
        ax = (uint16_t)svc_Random(0xC8, 0x190);
        room.timers[0] = ax;
    }
    if (rv_rlg_released == 1) {
        ax = (uint16_t)svc_Random(0xC8, 0x190);
        room.timers[1] = ax;
    }
    room.timers[2] = 0xC8;
    fv_cure_x = 0x89;
    fv_cure_y = 0xB9;
    return;
}

/* Exit 1 (timer 4): back to the crew quarters, room 4.
 * [MSG_EXIT 01 00 00] */
static void love5_ExitToQuarters(void)
{
    room.busy = 1;
    svc_BridgeSfx(5);
    room.timers[4] = 0xA;
    return;
}

/* [MSG_TIMER 04 00 00] */
static void love5_GoToQuarters(void)
{
    svc_GotoRoom(4, 0);
    room.busy = 0;
    return;
}

